#ifdef COBOL_CORE
extern void ledger_authorize(int64_t *source_balance, int64_t *amount_minor, int32_t *allowed, int64_t *debit_entry, int64_t *credit_entry);
static pthread_mutex_t cobol_core_lock=PTHREAD_MUTEX_INITIALIZER;
static int authorized(int64_t source_balance, int64_t amount_minor, int64_t *debit_entry, int64_t *credit_entry) {
    int32_t allowed = 0;
    pthread_mutex_lock(&cobol_core_lock);
    ledger_authorize(&source_balance, &amount_minor, &allowed, debit_entry, credit_entry);
    pthread_mutex_unlock(&cobol_core_lock);
    return allowed != 0;
}
#else
static int authorized(int64_t source_balance, int64_t amount_minor, int64_t *debit_entry, int64_t *credit_entry) {
    if (amount_minor <= 0 || source_balance < amount_minor) return 0;
    *debit_entry = -amount_minor;
    *credit_entry = amount_minor;
    return 1;
}
#endif

static const char *schema =
"CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,currency TEXT NOT NULL,balance_minor INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);"
"CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,from_account TEXT NOT NULL,to_account TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,posted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);"
"CREATE TABLE IF NOT EXISTS entries(id INTEGER PRIMARY KEY AUTOINCREMENT,transfer_id TEXT NOT NULL REFERENCES transfers(id),account_id TEXT NOT NULL REFERENCES accounts(id),amount_minor INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);"
"CREATE INDEX IF NOT EXISTS entries_account ON entries(account_id,id);";
static char db_path[1024];

typedef struct { struct timespec deadline; uint64_t operations; int valid; } memory_worker_t;
static int before_deadline(struct timespec now, struct timespec end) { return now.tv_sec<end.tv_sec || (now.tv_sec==end.tv_sec && now.tv_nsec<end.tv_nsec); }
static void *memory_worker(void *arg) {
    memory_worker_t *w=arg; int64_t left=INT64_C(1000000000000),right=INT64_C(1000000000000); uint64_t n=0;
    struct timespec now;
    while(clock_gettime(CLOCK_MONOTONIC,&now)==0 && before_deadline(now,w->deadline)) {
        int64_t debit=0,credit=0;
        int ok=(n&1)?authorized(right,1,&debit,&credit):authorized(left,1,&debit,&credit);
        if(!ok)break;
        if(n&1){right+=debit;left+=credit;}else{left+=debit;right+=credit;}
        n++;
    }
    w->operations=n;w->valid=(left+right)==INT64_C(2000000000000);return NULL;
}

static int db_open(sqlite3 **db) {
    if (sqlite3_open_v2(db_path, db, SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_FULLMUTEX, NULL) != SQLITE_OK) return 0;
    sqlite3_busy_timeout(*db, 30000);
    sqlite3_exec(*db, "PRAGMA foreign_keys=ON;", NULL, NULL, NULL);
    return 1;
}
static void make_id(char out[33]) {
    unsigned char b[16]; sqlite3_randomness(16,b);
    for (int i=0;i<16;i++) { sprintf(out+i*2,"%02x",b[i]); }
    out[32]='\0';
}
static void seed(sqlite3 *db) {
    sqlite3_exec(db,schema,NULL,NULL,NULL);
    sqlite3_exec(db,"PRAGMA journal_mode=WAL",NULL,NULL,NULL);
    sqlite3_exec(db,"ALTER TABLE accounts ADD COLUMN balance_minor INTEGER NOT NULL DEFAULT 0",NULL,NULL,NULL);
    sqlite3_exec(db,"UPDATE accounts SET balance_minor=COALESCE((SELECT SUM(amount_minor) FROM entries WHERE entries.account_id=accounts.id),0)",NULL,NULL,NULL);
    sqlite3_exec(db,"INSERT OR IGNORE INTO accounts(id,currency) VALUES('demo-alice','USD'),('demo-bob','USD'),('ledgerlab-funder','USD'),('demo-clearing','USD');",NULL,NULL,NULL);
    const char *keys[]={"ledgerlab-opening-funder-v1","ledgerlab-opening-alice-v1","ledgerlab-opening-bob-v1"};
    const char *targets[]={"ledgerlab-funder","demo-alice","demo-bob"};
    const int64_t amounts[]={INT64_C(1000000000000000),250000,250000};
    for(int i=0;i<3;i++){
        sqlite3_stmt *q=NULL;sqlite3_prepare_v2(db,"SELECT 1 FROM transfers WHERE idempotency_key=?1",-1,&q,NULL);sqlite3_bind_text(q,1,keys[i],-1,SQLITE_STATIC);int exists=sqlite3_step(q)==SQLITE_ROW;sqlite3_finalize(q);if(exists)continue;
        char id[33];make_id(id);sqlite3_stmt *s=NULL;
        sqlite3_prepare_v2(db,"INSERT INTO transfers(id,idempotency_key,request_hash,from_account,to_account,amount_minor,currency) VALUES(?1,?2,'synthetic-opening-v1','demo-clearing',?3,?4,'USD')",-1,&s,NULL);
        sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,keys[i],-1,SQLITE_STATIC);sqlite3_bind_text(s,3,targets[i],-1,SQLITE_STATIC);sqlite3_bind_int64(s,4,amounts[i]);sqlite3_step(s);sqlite3_finalize(s);
        sqlite3_prepare_v2(db,"INSERT INTO entries(transfer_id,account_id,amount_minor) VALUES(?1,'demo-clearing',?2),(?1,?3,?4)",-1,&s,NULL);
        sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,2,-amounts[i]);sqlite3_bind_text(s,3,targets[i],-1,SQLITE_STATIC);sqlite3_bind_int64(s,4,amounts[i]);sqlite3_step(s);sqlite3_finalize(s);
        sqlite3_prepare_v2(db,"UPDATE accounts SET balance_minor=balance_minor-?1 WHERE id='demo-clearing'",-1,&s,NULL);sqlite3_bind_int64(s,1,amounts[i]);sqlite3_step(s);sqlite3_finalize(s);
        sqlite3_prepare_v2(db,"UPDATE accounts SET balance_minor=balance_minor+?1 WHERE id=?2",-1,&s,NULL);sqlite3_bind_int64(s,1,amounts[i]);sqlite3_bind_text(s,2,targets[i],-1,SQLITE_STATIC);sqlite3_step(s);sqlite3_finalize(s);
    }
}
